var param = {
	"id":"ggb",
	"height":500,
	"showToolBar":false,
	"borderColor":null,
	"showMenuBar":false,
	"showAlgebraInput":false,
	"showResetIcon":false,
	"enableLabelDrags":false,
	"enableShiftDragZoom":true,
	"enableRightClick":false,
	"capturingThreshold":null,
	"showToolBarHelp":false,
	"errorDialogsActive":false,
	"useBrowserForJS":true,
	"ggbBase64":""};
var ggbApplet = new GGBApplet(param, '5.0');
ggbApplet.setHTML5Codebase("/vendor/geogebra/GeoGebra/HTML5/5.0/web3d/");
window.onload = function() {
	ggbApplet.inject('geogebra','preferHTML5');
}

ggb = document.ggb;
quadrica = 'cone';
plano = 'planoZ';
ggbInit = false;

function gerarSolido() {
	var func = document.getElementById('funcao');
	var a = document.getElementById('valor-a');
	var b = document.getElementById('valor-b');

	ggb.evalCommand("a = "+a.value);
	ggb.evalCommand("b = "+b.value);
	ggb.evalCommand("f(x) = "+func.value);

	eixoX();
}

function exibirAreaX() {
	var areax;
	areax = ggb.getLaTeXString("ax");
	document.getElementById("resultadox").style.display = "block";
	document.getElementById("res-ax").innerHTML = areax;
	ocultarAreaY();
}

function exibirAreaY() {
	var areay;
	areay = ggb.getLaTeXString("ay");
	document.getElementById("resultadoy").style.display = "block";
	document.getElementById("res-ay").innerHTML = areay;
	ocultarAreaX();
}

function ocultarAreaX() {
	document.getElementById("resultadox").style.display = "none";
}

function ocultarAreaY() {
	document.getElementById("resultadoy").style.display = "none";
}



function setRadianos() {
	var range = document.getElementById('radianos');
	ggb.setValue('alfa',range.value);

}

function animacao() {
	ggb.setValue('alfa', 0);
	ggb.evalCommand("StartAnimation[alfa]");
}

function eixoX() {
	ggb.evalCommand("SetVisibleInView(c, -1, true)");
	ggb.evalCommand("SetVisibleInView(d, -1, false)");
	exibirAreaX();
}

function eixoY() {
	ggb.evalCommand("SetVisibleInView(c, -1, false)");
	ggb.evalCommand("SetVisibleInView(d, -1, true)");
	exibirAreaY();
}